def solve():
    n = 3
    # a_k is the multiplicity of k in B = {b_0, ..., b_n}
    # b_k is the multiplicity of k in A = {a_0, ..., a_n}
    # sum(a_k) = n+1, sum(b_k) = n+1
    # a_k, b_k \in {0, 1, ..., n}

    import itertools
    # To optimize, we can use the fact that sum(a_k) = n+1
    # and a_k in {0, ..., n}.
    # The number of such sequences is the number of partitions of n+1 into n+1 parts.
    # For n=3, n+1=4, there are only a few.

    solutions = []
    for a in itertools.product(range(n + 1), repeat=n + 1):
        if sum(a) == n + 1:
            # calculate b
            b = [0] * (n + 1)
            for x in a:
                if x <= n:
                    b[x] += 1

            # calculate new_a
            new_a = [0] * (n + 1)
            for x in b:
                if x <= n:
                    new_a[x] += 1

            if list(new_a) == list(a):
                solutions.append(a)

    return solutions

